#include <bits/stdc++.h>
using namespace std; using LL=long long; using G=vector<int>;
void need(bool b,string s){if(!b)throw runtime_error(s);}
G induced(const G&a,const vector<int>&p){G b(p.size());for(int i=0;i<(int)p.size();i++)for(int j=0;j<(int)p.size();j++)if(a[p[i]]>>p[j]&1)b[i]|=1<<j;return b;}
G converse(G a){int m=(1<<a.size())-1;for(int i=0;i<(int)a.size();i++)a[i]^=m^(1<<i);return a;}
vector<vector<LL>> starts(const G&a){int n=a.size(),N=1<<n;vector<vector<LL>> d(N,vector<LL>(n));for(int s=1;s<N;s++)for(int v=0;v<n;v++)if(s>>v&1){if(s==(1<<v)){d[s][v]=1;continue;}int q=a[v]&(s^(1<<v));while(q){int u=__builtin_ctz(q);q&=q-1;d[s][v]+=d[s^(1<<v)][u];}}return d;}
array<LL,4> prof(const G&a,int r){auto d=starts(a);int N=1<<a.size();vector<LL> h(N,1);for(int s=1;s<N;s++)h[s]=accumulate(d[s].begin(),d[s].end(),0LL);LL R=0;for(int s=1;s<N;s++)if(s>>r&1)R+=d[s][r]*h[(N-1)^s];auto rev=starts(converse(a));return {h.back(),rev.back()[r],R,h[(N-1)^(1<<r)]};}
G key(const G&a,int r,const vector<vector<LL>>&d){int s=(1<<a.size())-1;vector<int> p={r};while(p.size()<a.size()){s^=1<<r;int found=-1;for(int u=0;u<(int)a.size();u++)if((s>>u&1)&&(a[r]>>u&1)&&d[s][u]){need(found<0,"unique path");found=u;}need(found>=0,"path continuation");p.push_back(r=found);}return induced(a,p);}
G build(const G&V,const G&W,int k){int n=V.size(),m=W.size(),N=n+m+k;G a(N);for(int i=0;i<n;i++)a[i]=V[i];int b=n;a[b]|=1;for(int i=1;i<n;i++)a[i]|=1<<b;if(k==2){int u=n+1;a[u]|=1<<b;for(int i=0;i<n;i++)a[i]|=1<<u;}G R=converse(W);for(int j=0;j<m;j++)a[n+k+j]=R[j]<<(n+k);for(int i=0;i<n+k;i++)for(int j=0;j<m;j++){if(j==0&&(i==0||i==n+k-1))a[n+k+j]|=1<<i;else a[i]|=1<<(n+k+j);}return a;}
LL scalar(int k,array<LL,4>v,array<LL,4>w){auto[D,E,U,d]=v;auto[g,s,L,f]=w;if(k==1)return (D-E+U)*g-(D-E+d)*s+(D+3*U-d)*L-(U+E)*f;return (D+2*U)*g-(U+d)*s+(2*D-E+6*U-d)*L-(U+E)*f;}
vector<vector<int>> maps(const G&a,bool anti){int n=a.size();vector<int>deg(n),p(n,-1);vector<vector<int>> cand(n),out;for(int i=0;i<n;i++)deg[i]=__builtin_popcount(a[i]);for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(deg[j]==(anti?n-1-deg[i]:deg[i]))cand[i].push_back(j);function<void(int)> rec=[&](int used){if(used==(1<<n)-1){out.push_back(p);return;}int v=-1;vector<int>good;for(int i=0;i<n;i++)if(p[i]<0){vector<int>cur;for(int j:cand[i])if(!(used>>j&1)){bool ok=true;for(int t=0;t<n;t++)if(p[t]>=0&&((a[i]>>t&1)^anti)!=(a[j]>>p[t]&1)){ok=false;break;}if(ok)cur.push_back(j);}if(v<0||cur.size()<good.size()){v=i;good=cur;}}for(int j:good){p[v]=j;rec(used|(1<<j));p[v]=-1;}};rec(0);return out;}
pair<LL,LL> literal_counts(const G&a){int n=a.size(),all=(1<<n)-1;LL H=0,C=0;function<void(int,int,int)> visit=[&](int first,int last,int mask){if(mask==all){H++;if(first==0&&(a[last]&1))C++;return;}int z=a[last]&(all^mask);while(z){int v=__builtin_ctz(z);z&=z-1;visit(first,v,mask|(1<<v));}};for(int v=0;v<n;v++)visit(v,v,1<<v);return {H,C};}
int main(){map<int,set<G>> bank;LL labelled=0,rooted=0;for(int n=1;n<=6;n++){int e=n*(n-1)/2;for(int c=0;c<(1<<e);c++){G a(n);int z=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,z++)if(c>>z&1)a[i]|=1<<j;else a[j]|=1<<i;auto d=starts(a);labelled++;for(int r=0;r<n;r++)if(d.back()[r]==1){bank[n].insert(key(a,r,d));rooted++;}}}vector<int>expected={0,1,1,2,5,13,34};for(int n=1;n<=6;n++)need(bank[n].size()==expected[n],"independent source inventory");map<G,array<LL,4>> profiles;for(auto&[n,ss]:bank)for(auto&a:ss){auto v=prof(a,0);need(v[0]%2==1&&(v[2]-v[1])%2==0,"source parity");profiles[a]=v;}
LL graphs=0,swaps=0,sc=0;map<int,int>counts,scounts;for(int n=2;n<=6;n++)for(int m=2;m<=6;m++)for(int k=1;k<=2;k++)if(n+m+k<=10)for(auto&V:bank[n])for(auto&W:bank[m]){G a=build(V,W,k),other=build(W,V,k);int N=a.size();vector<int>p(N);for(int i=0;i<n;i++)p[i]=m+k+i;for(int j=0;j<m;j++)p[n+k+j]=j;if(k==1)p[n]=m;else{p[n]=m+1;p[n+1]=m;}for(int i=0;i<N;i++)for(int j=0;j<N;j++)if(i!=j)need((a[i]>>j&1)!=(other[p[i]]>>p[j]&1),"literal swap");swaps++;auto[H,C]=literal_counts(a);need(C==2&&H==scalar(k,profiles[V],profiles[W]),"literal scalar cycles");auto anti=maps(a,true),aut=maps(a,false);need(aut.size()==1,"literal rigidity");bool same=V==W;need(!anti.empty()==same,"anti iff canonical source equal");if(same){sc++;scounts[N]++;need(H%4==1&&anti.size()==1,"diagonal residue and unique anti");int f=0;for(int i=0;i<N;i++){need(anti[0][anti[0][i]]==i,"involution");f+=anti[0][i]==i;}need(f==2-k,"fixed vertex count");}graphs++;counts[N]++;}
G R5={6,12,24,17,3};need(literal_counts(R5)==make_pair(15LL,2LL)&&maps(R5,true).size()==5&&maps(R5,false).size()==5,"R5 exception");scounts[5]++;vector<int>sc_expected={2,1,2,2,5,5};for(int n=5;n<=10;n++)need(scounts[n]==sc_expected[n-5],"all diagonal GF coefficients");G A={124,65,122,114,98,2,32},B={124,113,122,66,104,8,32};auto da=starts(A),db=starts(B);A=key(A,5,da);B=key(B,5,db);need(A!=B&&prof(A,0)==prof(B,0)&&prof(A,0)==array<LL,4>{27,9,27,9},"literal source collision");G bad=build(A,B,1),good=build(A,A,1);need(literal_counts(bad)==make_pair(3321LL,2LL)&&literal_counts(good)==make_pair(3321LL,2LL),"literal hostile counts");need(maps(bad,true).empty()&&maps(good,true).size()==1,"literal hostile anti sets");need(maps(bad,false).size()==1&&maps(good,false).size()==1,"literal hostile rigidity");
cout<<"{\n  \"status\": \"PASS\",\n  \"labelled_source_graphs\": "<<labelled<<",\n  \"rooted_start_one_inputs\": "<<rooted<<",\n  \"canonical_source_counts\": [1,1,2,5,13,34],\n  \"literal_pair_graphs\": "<<graphs<<",\n  \"literal_swaps\": "<<swaps<<",\n  \"full_automorphism_checks\": "<<graphs+3<<",\n  \"full_anti_isomorphism_checks\": "<<graphs+3<<",\n  \"self_converse_counts_orders_5_to_10\": [2,1,2,2,5,5],\n  \"hostile_H\": 3321\n}\n";
}
